<?php $activeMenu='router';$routerView='system';require_once __DIR__.'/../includes/sidebar.php'; ?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>System Router - NetMonitor</title><link rel="stylesheet" href="../assets/css/variables.css"><link rel="stylesheet" href="../assets/css/common.css"><link rel="stylesheet" href="../assets/css/theme.css?v=1"><style>body{margin:0}.page{margin-left:220px;padding:32px}.head{display:flex;justify-content:space-between;align-items:center;margin-bottom:22px}.title{font-size:28px;font-weight:700}.sub,.muted{color:#66758d}.btn{border:1px solid #d7e0ec;background:#fff;border-radius:8px;padding:10px 14px;font-weight:600;cursor:pointer}.primary{background:#087cff;color:#fff;border-color:#087cff}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:16px;margin-bottom:18px}.card{background:#fff;border:1px solid #dce4ef;border-radius:14px;padding:18px}.label{font-size:11px;text-transform:uppercase;color:#718096;letter-spacing:.4px}.value{font-size:22px;font-weight:700;margin-top:8px}.small{font-size:12px;color:#66758d;margin-top:5px}.info{display:grid;grid-template-columns:1fr 1fr;gap:16px}.row{display:flex;justify-content:space-between;padding:12px 0;border-bottom:1px solid #edf1f6;font-size:13px}.row:last-child{border-bottom:0}.meter{height:8px;background:#edf1f6;border-radius:9px;overflow:hidden;margin-top:12px}.fill{height:100%;background:#087cff;width:0}.notice{color:#b42318}@media(max-width:900px){.grid{grid-template-columns:1fr 1fr}}@media(max-width:600px){.page{margin-left:0;padding:20px}.grid,.info{grid-template-columns:1fr}.head{align-items:flex-start;flex-direction:column;gap:12px}}</style></head><body><main class="page"><div class="head"><div><div class="title">System Router</div><div class="sub">Resource dan informasi sistem MikroTik.</div></div><button class="btn primary" id="refresh">↻ Refresh</button></div><div class="grid"><div class="card"><div class="label">CPU Load</div><div class="value" id="cpu">-</div><div class="meter"><div class="fill" id="cpuBar"></div></div></div><div class="card"><div class="label">Memory</div><div class="value" id="mem">-</div><div class="small" id="memFree">-</div></div><div class="card"><div class="label">Storage</div><div class="value" id="disk">-</div><div class="small" id="diskFree">-</div></div><div class="card"><div class="label">Uptime</div><div class="value" id="uptime">-</div><div class="small" id="updated">Belum diperbarui</div></div></div><div class="info"><div class="card"><h3>Informasi Router</h3><div class="row"><span>Identity</span><b id="identity">-</b></div><div class="row"><span>Board</span><b id="board">-</b></div><div class="row"><span>Architecture</span><b id="arch">-</b></div><div class="row"><span>RouterOS</span><b id="version">-</b></div></div><div class="card"><h3>Clock</h3><div class="row"><span>Tanggal</span><b id="date">-</b></div><div class="row"><span>Waktu</span><b id="time">-</b></div><div class="row"><span>Timezone</span><b id="tz">-</b></div><div class="row"><span>Router</span><b id="router">-</b></div></div></div></main><script>const $=id=>document.getElementById(id),fmt=n=>{n=Number(n)||0;if(n<1024)return n.toFixed(0)+' B';if(n<1048576)return(n/1024).toFixed(1)+' KB';if(n<1073741824)return(n/1048576).toFixed(1)+' MB';return(n/1073741824).toFixed(2)+' GB'};async function load(){try{const r=await fetch('../api/router_system.php?nocache='+Date.now(),{cache:'no-store'}),d=await r.json();if(d.status!=='online')throw Error(d.message||'Router offline');$('identity').textContent=d.identity;$('board').textContent=d.board;$('arch').textContent=d.architecture;$('version').textContent=d.version;$('router').textContent=d.router;$('uptime').textContent=d.uptime;$('cpu').textContent=d.cpu_load+'%';$('cpuBar').style.width=Math.min(100,Number(d.cpu_load)||0)+'%';$('mem').textContent=fmt((Number(d.memory_total)||0)-(Number(d.memory_free)||0));$('memFree').textContent='Free '+fmt(d.memory_free)+' / '+fmt(d.memory_total);$('disk').textContent=fmt((Number(d.hdd_total)||0)-(Number(d.hdd_free)||0));$('diskFree').textContent='Free '+fmt(d.hdd_free)+' / '+fmt(d.hdd_total);$('date').textContent=d.date;$('time').textContent=d.clock;$('tz').textContent=d.timezone;$('updated').textContent='Update '+new Date().toLocaleTimeString('id-ID')}catch(e){$('updated').textContent='Gagal: '+e.message}}$('refresh').onclick=load;load();setInterval(load,10000)</script><script src="../assets/js/app.js?v=6"></script></body></html>